/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png'))
# print rough pixels at tap and glass bottom
for y in range(0,61,2):
 vals=[]
 for x in range(128,160,2):
  r,g,b=im[y,x]
  if int(r)>120 and int(r)>int(g)*1.2: vals.append('R')
  elif int(r)>200 and int(g)>200: vals.append('W')
  elif int(b)>120 and int(b)>int(r)*1.1: vals.append('B')
  elif int(r)<60 and int(g)<60: vals.append('K')
  elif int(r)>110 and int(g)>90 and int(b)<100: vals.append('T')
  else: vals.append('.')
 print(f'{y:3}', ''.join(vals))
PY"
